import { Injectable } from '@angular/core';
import { HttpClient, HttpHeaders } from '@angular/common/http';
import { Observable } from 'rxjs';
import { environment } from '../../environments/environment';

@Injectable({
  providedIn: 'root'
})
export class ApiService {
  private apiUrl = environment.apiUrl;

  constructor(private http: HttpClient) { }

  private getHeaders() {
    const token = localStorage.getItem('token');
    let headers = new HttpHeaders();
    if (token) {
      headers = headers.set('Authorization', `Token ${token}`);
    }
    return headers;
  }

  getIncidents(): Observable<any> {
    return this.http.get(`${this.apiUrl}/incidents/`);
  }

  createIncident(incident: any): Observable<any> {
    return this.http.post(`${this.apiUrl}/incidents/`, incident, { headers: this.getHeaders() });
  }

  login(credentials: any): Observable<any> {
    return this.http.post(`${this.apiUrl}/users/login/`, credentials);
  }

  register(userData: any): Observable<any> {
    return this.http.post(`${this.apiUrl}/users/`, userData);
  }

  getMe(): Observable<any> {
    return this.http.get(`${this.apiUrl}/users/me/`, { headers: this.getHeaders() });
  }

  updateProfile(userId: number, profileData: any): Observable<any> {
    return this.http.patch(`${this.apiUrl}/users/${userId}/`, profileData, { headers: this.getHeaders() });
  }
}
